function applyLang(code){lang=langs[code]?code:"en";localStorage.setItem("fafurion_lang",lang);localStorage.setItem("fafurion-language",lang);localStorage.setItem("fafurion_language",lang);const L=langs[lang];document.documentElement.lang=lang;document.getElementById("currentFlag").src="assets/flags/"+L.flag+".svg";document.getElementById("currentLang").textContent=L.name;document.querySelectorAll("[data-i18n]").forEach(el=>{const k=el.dataset.i18n;if(L.t[k])el.textContent=L.t[k]});document.querySelectorAll(".lang-option").forEach(b=>b.classList.toggle("active",b.dataset.lang===lang));document.getElementById("langBox").classList.remove("open")}


const defaultWheelRewards=[
{id:"57",name:"Adena",amount:"5,000,000",chance:25,icon:"A"},
{id:"4037",name:"Event Coin",amount:"100",chance:20,icon:"C"},
{id:"959",name:"Enchant Scroll",amount:"2",chance:15,icon:"S"},
{id:"6622",name:"Giant's Codex",amount:"1",chance:12,icon:"G"},
{id:"10480",name:"Life Stone",amount:"3",chance:10,icon:"L"},
{id:"70001",name:"Vote Point Pack",amount:"250",chance:8,icon:"V"},
{id:"80001",name:"Mystery Box",amount:"1",chance:7,icon:"?"},
{id:"90001",name:"Jackpot Chest",amount:"1",chance:3,icon:"★",jackpot:true}
];
let wheelRewards=[],playerWheelRotation=0,adminWheelRotation=0,wheelSpinning=false;
function escWheel(v){return String(v).replace(/[&<>"']/g,m=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[m]))}
function loadWheelConfig(){try{const s=JSON.parse(localStorage.getItem("fafurionWheelConfig")||"null");wheelRewards=Array.isArray(s)&&s.length>=2?s:defaultWheelRewards.map(x=>({...x}))}catch(e){wheelRewards=defaultWheelRewards.map(x=>({...x}))}}
function wheelGradient(n){const p=["#183a45","#4c3d25","#12313b","#3f2d28","#143843","#453923","#142f39","#593d20","#163945","#4a3525","#15323c","#493b22"],step=360/n;return "conic-gradient(from -"+(step/2)+"deg,"+Array.from({length:n},(_,i)=>p[i%p.length]+" "+(i*step)+"deg "+((i+1)*step)+"deg").join(",")+")"}
function renderWheel(id){const c=document.getElementById(id);if(!c||!wheelRewards.length)return;c.style.background=wheelGradient(wheelRewards.length);const r=id==="adminWheelSegments"?100:135;c.innerHTML=wheelRewards.map((x,i)=>{const a=i*(360/wheelRewards.length);return '<div class="wheel-segment-label" style="transform:rotate('+a+'deg) translateY(-'+r+'px) rotate('+(-a)+'deg)"><span>'+(x.icon||"◆")+'</span><b>'+escWheel(x.name)+'</b><small>x'+escWheel(x.amount)+'</small></div>'}).join("")}
function renderWheelRewardGrid(){const g=document.getElementById("wheelRewardGrid");if(!g)return;const total=wheelRewards.reduce((s,r)=>s+Number(r.chance||0),0),t=document.getElementById("wheelChanceTotal");if(t)t.textContent=total+"% total chance";g.innerHTML=wheelRewards.map(r=>'<div class="wheel-reward-card '+(r.jackpot?"jackpot":"")+'"><span class="reward-slot-icon">'+(r.icon||"◆")+'</span><div><b>'+escWheel(r.name)+' ×'+escWheel(r.amount)+'</b><small>Item ID '+escWheel(r.id)+'</small><em>'+r.chance+'% chance</em></div></div>').join("");updateJackpots()}
function updateJackpots(){const j=[...wheelRewards].sort((a,b)=>Number(a.chance)-Number(b.chance))[0];if(!j)return;[["jackpotName",j.name],["jackpotId",j.id],["jackpotAmount",j.amount],["jackpotChance",j.chance+"%"],["adminJackpotLabel",j.name+" · ID "+j.id+" · x"+j.amount],["adminJackpotChance",j.chance+"%"]].forEach(([id,v])=>{const e=document.getElementById(id);if(e)e.textContent=v})}
function pickWheelReward(){const total=wheelRewards.reduce((s,r)=>s+Math.max(0,Number(r.chance||0)),0)||1;let roll=Math.random()*total;for(let i=0;i<wheelRewards.length;i++){roll-=Math.max(0,Number(wheelRewards[i].chance||0));if(roll<=0)return i}return wheelRewards.length-1}
function wheelDateKey(){const d=new Date();return d.getFullYear()+"-"+String(d.getMonth()+1).padStart(2,"0")+"-"+String(d.getDate()).padStart(2,"0")}
function validateWheelCharacter(showToast=false){
  const select=document.getElementById("wheelCharacter"),warning=document.getElementById("wheelCharacterWarning");
  if(!select)return true;
  const online=select.options[select.selectedIndex]?.dataset.online==="1";
  select.classList.toggle("online-blocked",online);
  if(warning)warning.classList.toggle("show",online);
  if(online&&showToast){
    let toast=document.getElementById("demoToast");
    if(!toast){toast=document.createElement("div");toast.id="demoToast";toast.className="demo-toast";document.body.appendChild(toast)}
    toast.textContent=warning?.textContent||"Selected character must be offline before spinning.";
    toast.classList.add("show");clearTimeout(window.__demoToastTimer);window.__demoToastTimer=setTimeout(()=>toast.classList.remove("show"),3000);
  }
  return !online;
}
function spinDailyWheel(){if(wheelSpinning||!wheelRewards.length)return;if(!validateWheelCharacter(true))return;const today=wheelDateKey();if(localStorage.getItem("fafurionWheelLastSpinDate")===today){demoAction("wheelAlreadyUsed");return}wheelSpinning=true;const btn=document.getElementById("wheelSpinButton");if(btn)btn.disabled=true;const i=pickWheelReward(),step=360/wheelRewards.length;playerWheelRotation+=360*7-(i*step)+(Math.random()*step*.25-step*.125);const w=document.getElementById("luckyWheel");if(w)w.style.transform="rotate("+playerWheelRotation+"deg)";setTimeout(()=>{wheelSpinning=false;localStorage.setItem("fafurionWheelLastSpinDate",today);localStorage.setItem("fafurionWheelLastReward",JSON.stringify(wheelRewards[i]));updateDailyWheelState();showWheelResult(wheelRewards[i])},5500)}
function showWheelResult(r){[["wheelResultIcon",r.icon||"◆"],["wheelResultName",r.name+" ×"+r.amount],["wheelResultId",r.id],["wheelResultAmount",r.amount]].forEach(([id,v])=>{const e=document.getElementById(id);if(e)e.textContent=v});document.getElementById("wheelResultPop")?.classList.add("open");document.body.style.overflow="hidden"}
function closeWheelResult(){document.getElementById("wheelResultPop")?.classList.remove("open");document.body.style.overflow=""}
function secsToMidnight(){const n=new Date(),x=new Date(n);x.setHours(24,0,0,0);return Math.max(0,Math.floor((x-n)/1000))}
function fmtWheelTime(s){return String(Math.floor(s/3600)).padStart(2,"0")+":"+String(Math.floor((s%3600)/60)).padStart(2,"0")+":"+String(s%60).padStart(2,"0")}
function updateDailyWheelState(){const used=localStorage.getItem("fafurionWheelLastSpinDate")===wheelDateKey(),btn=document.getElementById("wheelSpinButton"),st=document.getElementById("wheelSpinStatus"),ct=document.getElementById("wheelCountdown"),adminReset=document.getElementById("adminWheelReset");if(btn&&!wheelSpinning)btn.disabled=used;if(st){st.classList.toggle("used",used);const b=st.querySelector("b");if(b)b.textContent=used?"USED TODAY":"READY NOW"}const remain=fmtWheelTime(secsToMidnight());if(ct)ct.textContent=used?remain:"READY";if(adminReset)adminReset.textContent=remain;document.querySelectorAll(".wheel-ready-dot").forEach(e=>e.style.display=used?"none":"grid")}
function renderWheelAdminRows(){const r=document.getElementById("wheelAdminRows");if(!r)return;r.innerHTML=wheelRewards.map((x,i)=>'<div class="wheel-admin-row" data-wheel-row="'+i+'"><span>'+(i+1)+'</span><input data-field="id" value="'+escWheel(x.id)+'"><input data-field="name" value="'+escWheel(x.name)+'"><input data-field="amount" value="'+escWheel(x.amount)+'"><input class="chance-input" data-field="chance" type="number" min="0" max="100" step=".1" value="'+x.chance+'"><button onclick="removeWheelReward('+i+')">×</button></div>').join("");updateAdminChanceTotal()}
function syncWheelRows(){const rows=[...document.querySelectorAll("#wheelAdminRows .wheel-admin-row")];if(!rows.length)return;wheelRewards=rows.map((row,i)=>{const v=f=>row.querySelector('[data-field="'+f+'"]')?.value||"";return{id:v("id"),name:v("name")||("Reward "+(i+1)),amount:v("amount")||"1",chance:Number(v("chance")||0),icon:wheelRewards[i]?.icon||"◆"}});const j=[...wheelRewards].sort((a,b)=>a.chance-b.chance)[0];if(j)j.jackpot=true}
function updateAdminChanceTotal(){let n=0;document.querySelectorAll('#wheelAdminRows [data-field="chance"]').forEach(i=>n+=Number(i.value||0));const e=document.getElementById("adminChanceTotal");if(e){e.textContent=n+"%";e.classList.toggle("bad",Math.abs(n-100)>.01)}}
function addWheelReward(){if(wheelRewards.length>=12){demoAction("wheelMaxRewards");return}syncWheelRows();wheelRewards.push({id:"0",name:"New Reward",amount:"1",chance:0,icon:"◆"});renderWheelAdminRows();previewWheelConfig()}
function removeWheelReward(i){if(wheelRewards.length<=2)return;syncWheelRows();wheelRewards.splice(i,1);renderWheelAdminRows();previewWheelConfig()}
function previewWheelConfig(){syncWheelRows();renderWheel("adminWheelSegments");renderWheel("wheelSegments");renderWheelRewardGrid();updateAdminChanceTotal();demoAction("wheelPreviewUpdated")}
function saveWheelConfig(){syncWheelRows();const total=wheelRewards.reduce((s,r)=>s+Number(r.chance||0),0);if(Math.abs(total-100)>.01){demoAction("wheelChanceError");return}localStorage.setItem("fafurionWheelConfig",JSON.stringify(wheelRewards));renderWheel("wheelSegments");renderWheel("adminWheelSegments");renderWheelRewardGrid();demoAction("wheelSaved")}
function adminPreviewSpin(){if(!wheelRewards.length)return;const i=pickWheelReward(),step=360/wheelRewards.length;adminWheelRotation+=360*5-(i*step);const e=document.getElementById("adminLuckyWheel");if(e)e.style.transform="rotate("+adminWheelRotation+"deg)"}
function initWheelFeature(){loadWheelConfig();renderWheel("wheelSegments");renderWheel("adminWheelSegments");renderWheelRewardGrid();renderWheelAdminRows();validateWheelCharacter(false);updateDailyWheelState();document.getElementById("wheelAdminRows")?.addEventListener("input",updateAdminChanceTotal);setInterval(updateDailyWheelState,1000)}

const adminTabTitles={overview:"Overview",players:"Players",donations:"Donations",support:"Support",content:"Content",wheel:"Wheel Manager",moderation:"Moderation",economy:"Economy",server:"Server",audit:"Audit Logs",staff:"Staff & Roles"};
function showAdminTab(tab){
  document.querySelectorAll(".admin-view").forEach(v=>v.classList.toggle("active",v.id==="admin-"+tab+"-view"));
  document.querySelectorAll("[data-admin-tab]").forEach(b=>b.classList.toggle("active",b.dataset.adminTab===tab));
  document.querySelectorAll("[data-admin-tab-mobile]").forEach(b=>b.classList.toggle("active",b.dataset.adminTabMobile===tab));
  const t=document.getElementById("adminPageTitle");if(t)t.textContent=adminTabTitles[tab]||tab;
  window.scrollTo({top:0,behavior:"smooth"});
}

