function filterAdminPlayers(){
  const q=(document.getElementById("adminPlayerSearch")?.value||"").toLowerCase();
  const s=document.getElementById("adminPlayerFilter")?.value||"all";
  document.querySelectorAll("#adminPlayersTable tbody tr").forEach(row=>{
    const matchesText=row.textContent.toLowerCase().includes(q);
    const matchesStatus=s==="all"||row.dataset.status===s;
    row.style.display=matchesText&&matchesStatus?"":"none";
  });
}
