let voteResetSeconds=11*3600+42*60+18;
function updateVoteReset(){
  const el=document.getElementById("voteResetClock"); if(!el)return;
  const h=String(Math.floor(voteResetSeconds/3600)).padStart(2,"0");
  const m=String(Math.floor((voteResetSeconds%3600)/60)).padStart(2,"0");
  const s=String(voteResetSeconds%60).padStart(2,"0");
  el.textContent=h+":"+m+":"+s; voteResetSeconds=Math.max(0,voteResetSeconds-1);
}
setInterval(updateVoteReset,1000);updateVoteReset();
function claimReward(btn,type){
  if(btn.classList.contains("claimed"))return;
  btn.classList.add("claimed");
  const original=btn.textContent;
  btn.textContent="✓ CLAIMED";
  btn.disabled=true;
  if(type==="daily"){
    const current=document.querySelector(".day-box.current");
    if(current){current.classList.remove("current");current.classList.add("claimed");current.querySelector("b").textContent="✓";}
  }
  demoAction("reward");
}
