let eventCountdownTimer=null;
function formatEventCountdown(total){
  total=Math.max(0,Math.floor(total));
  const d=Math.floor(total/86400);
  const h=String(Math.floor((total%86400)/3600)).padStart(2,"0");
  const m=String(Math.floor((total%3600)/60)).padStart(2,"0");
  const s=String(total%60).padStart(2,"0");
  return d>0?String(d).padStart(2,"0")+":"+h+":"+m+":"+s:h+":"+m+":"+s;
}
function tickEventCountdowns(){
  document.querySelectorAll("[data-event-countdown]").forEach(el=>{
    let value=Number(el.dataset.eventCountdown||0);
    el.textContent=formatEventCountdown(value);
    if(value>0)el.dataset.eventCountdown=String(value-1);
  });
}
