function runAccountAnimations(){
  document.querySelectorAll("#page-account [data-count]").forEach(el=>{
    const target=Number(el.dataset.count||0);
    const start=performance.now();
    const duration=850;
    function tick(now){
      const p=Math.min((now-start)/duration,1);
      const eased=1-Math.pow(1-p,3);
      el.textContent=Math.round(target*eased).toLocaleString();
      if(p<1)requestAnimationFrame(tick);
    }
    requestAnimationFrame(tick);
  });
  document.querySelectorAll("#page-account [data-progress]").forEach(el=>{
    el.style.width="0%";
    requestAnimationFrame(()=>requestAnimationFrame(()=>el.style.width=el.dataset.progress+"%"));
  });
}
